","source_url":"https://kurasu.kyoto/blogs/kurasu-journal/flash-brew-iced-coffee-kenya-kangocho-aa-brazil-joao-hamilton"},{"slug":"coffee-supreme-au-south-blend-espresso","source_url":"https://shopau.coffeesupreme.com/products/south-blend"}]$expected_recipes$::jsonb)), curator as (select id from public.profiles where username='beanmora_official')
select count(*) as expected_recipes,
  count(r.id) as present_recipes,
  count(*) filter(where r.visibility='public' and r.user_id=(select id from curator)) as public_curator_recipes,
  count(*) filter(where r.bean_id is not null) as recipes_linked_to_coffee,
  count(*) filter(where r.is_incomplete_source) as incomplete_sources,
  count(*) filter(where r.brew_method='espresso') as espresso_specs,
  count(*) filter(where r.brew_method='espresso' and r.water_grams is not null) as invalid_espresso_input_water,
  count(*) filter(where exists(select 1 from public.recipe_sources s where s.recipe_id=r.id and s.source_url=e.value->>'source_url' and s.data_confidence='official')) as official_primary_source_links,
  count(*) filter(where exists(select 1 from public.roasters ro where ro.id::text=r.source_brew_parameters->'discovery'->>'roaster_id')) as resolved_roaster_ids,
  count(*) filter(where jsonb_typeof(r.source_brew_parameters->'discovery'->'applicable_coffee_names')='array') as shared_name_arrays,
  count(*) filter(where r.cover_image_url is not null) as recipes_with_covers,
  count(*) filter(where r.cover_image_url=r.source_brew_parameters->'global_roasters_import'->>'photo_url') as covers_matching_verified_selection
from expected e left join public.recipes r on r.slug=e.value->>'slug';

