state-rico-beba7bc3","source_url":"https://www.tobysestate.com.au/rico/","image_url":"https://cdn11.bigcommerce.com/s-m2isrqnxtu/products/306/images/1101/Rico_WEB_IMAGE_200G__01306.1774586487.386.513.png?c=1","image_kind":"packaging"},{"slug":"toby-s-estate-black-swan-48b18a55","source_url":"https://www.tobysestate.com.au/brew-guides/","image_url":"https://cdn11.bigcommerce.com/s-m2isrqnxtu/images/stencil/original/image-manager/blackswan-1800x1200.png?t=1751968458","image_kind":"packaging"},{"slug":"toby-s-estate-organic-blend-b66f36a7","source_url":"https://www.tobysestate.com.au/organic-blend/","image_url":"https://cdn11.bigcommerce.com/s-m2isrqnxtu/products/309/images/1095/Organic_WEB_IMAGE_200G_New__56631.1774586090.386.513.png?c=1","image_kind":"packaging"},{"slug":"toby-s-estate-decaf-3ce1f280","source_url":"https://www.tobysestate.com.au/decaf/","image_url":"https://cdn11.bigcommerce.com/s-m2isrqnxtu/products/311/images/575/decaf_new_apr23_web_200g__17074.1767519753.386.513.png?c=1","image_kind":"packaging"},{"slug":"toby-s-estate-brunswick-13d58070","source_url":"https://www.tobysestate.com.au/brunswick/","image_url":"https://cdn11.bigcommerce.com/s-m2isrqnxtu/products/310/images/1093/Brunswick_WEB_IMAGE_200G_New__06205.1774585975.386.513.png?c=1","image_kind":"packaging"},{"slug":"five-senses-coffee-ardi-be105bb3","source_url":"https://fivesenses.com.au/products/ardi-ethiopia","image_url":"https://cdn.shopify.com/s/files/1/0624/5430/0844/products/SO-Ardi-Ethiopia.png?v=1655347881","image_kind":"packaging"},{"slug":"five-senses-coffee-umoja-washed-bffa1c95","source_url":"https://fivesenses.com.au/products/umoja-washed-tanzania","image_url":"https://cdn.shopify.com/s/files/1/0624/5430/0844/files/Umoja-Washed-250g.png?v=1685672074","image_kind":"packaging"},{"slug":"five-senses-coffee-sweater-weather-blend-89c39ff6","source_url":"https://fivesenses.com.au/products/sweater-weather-blend","image_url":"https://cdn.shopify.com/s/files/1/0624/5430/0844/products/sweaterweather.png?v=1655351008","image_kind":"packaging"},{"slug":"coffee-supreme-au-south-blend-5edb4464","source_url":"https://shopau.coffeesupreme.com/products/south-blend","image_url":"https://shopau.coffeesupreme.com/cdn/shop/files/AU-Coffee-Supreme_South-Blend_1kg_79c66a86-02b4-40e0-9f7d-10789f9d092b_1024x1024.png?v=1747018493","image_kind":"packaging"}]$expected_beans$::jsonb))
select count(*) as expected_added_coffees,count(b.id) as present_coffees,
  count(*) filter(where b.is_published and not b.requires_review and b.data_confidence='official') as reviewed_public_coffees,
  count(*) filter(where b.source_url=e.value->>'source_url' and b.image_url=e.value->>'image_url' and b.image_usage_status='source_linked') as exact_source_linked_photos,
  count(*) filter(where b.image_kind='packaging') as packaging,
  count(*) filter(where b.image_kind='product_artwork') as product_artwork,
  count(*) filter(where b.sensory_profile <> '{}'::jsonb) as sourced_sensory_profiles
from expected e left join public.beans b on b.slug=e.value->>'slug';

select r.slug,r.water_grams,r.total_time_seconds,
  r.source_brew_parameters->'manual' as reviewed_output_parameters
from public.recipes r where r.visibility='public' and r.slug in ('crema-coffee-espresso','equator-espresso','flair-58-starter-espresso') order by r.slug;

select r.id='b93e7d45-b98b-40e2-972b-3b3960672d28'::uuid as preserved_monarch_id,
  r.visibility='public' as still_public,r.bean_id is not null as coffee_link_added,
  exists(select 1 from public.recipe_sources s where s.recipe_id=r.id and s.source_url='https://onyxcoffeelab.com/pages/help-me-brew') as retained_previous_source,
  exists(select 1 from public.recipe_sources s where s.recipe_id=r.id and s.source_url='https://onyxcoffeelab.com/products/monarch') as added_product_source
from public.recipes r where r.slug='onyx-monarch-kalita-wave';
